/**
 * Generate a complete `Window['electron']` mock surface from `IElectronAPI`.
 *
 * Unimplemented methods warn once and return a typed default. `on*` subscriptions
 * register on BrowserMockRuntime. Run `bun run web:preview:codegen` after the
 * preload contract changes, and commit the generated files.
 *
 * The generator uses the TypeScript 7 checker API, which must run on Node
 * (its sync channel reads a Node file descriptor).
 */
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { isInterfaceDeclaration, type Node } from 'typescript/unstable/ast';
import {
  API,
  ObjectFlags,
  SignatureKind,
  SymbolFlags,
  TypeFlags,
  type Checker,
  type Project,
  type Signature,
  type Symbol,
  type Type,
} from 'typescript/unstable/sync';

const ROOT = path.resolve(import.meta.dirname, '../..');
const OUT_DIR = path.join(ROOT, 'src/renderer/browserMock/generated');
const HEADER = '// Generated by scripts/preview/generate-browser-mock.ts. Do not edit.\n';
const MAX_LINES = 800;
const MAX_DEPTH = 14;

const TRUE_NAMES = new Set([
  'success',
  'ok',
  'hasConfig',
  'loggedIn',
  'installed',
  'isDev',
  'managedByApp',
  'exists',
]);
const STRING_BY_NAME: Record<string, string> = {
  platform: 'darwin',
  arch: 'arm64',
  version: '0.0.0-preview',
  id: 'preview',
  name: 'Preview',
  title: 'Preview',
  path: '/home/user/preview',
  cwd: '/home/user/preview',
  url: 'https://example.com',
  baseURL: 'https://api.example.com/v1',
  model: 'preview-model',
  message: 'Preview',
};
const OPTIONAL_OBJECTS = new Set([
  'config',
  'status',
  'session',
  'data',
  'result',
  'snapshot',
  'state',
  'skills',
  'servers',
  'tasks',
  'workspaces',
  'models',
  'agents',
  'runs',
  'catalog',
  'workspace',
  'item',
  'task',
  'skill',
  'server',
]);
const PREFERRED_LITERALS = [
  'idle',
  'stopped',
  'completed',
  'succeeded',
  'success',
  'ok',
  'ready',
  'none',
  'pass',
  'waiting',
  'manual',
  'auto',
  'ask',
  'work',
  'openai',
  'darwin',
  'info',
  'open',
  'disabled',
  'direct',
  'group',
  'feishu',
  'pairing',
  'allowlist',
  'text',
  'stdio',
  'system',
  'preset',
];

interface PropChunk {
  name: string;
  lines: string[];
}

function exportName(prop: string): string {
  return `create${prop.charAt(0).toUpperCase()}${prop.slice(1)}`;
}

function ident(name: string): string {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) ? name : JSON.stringify(name);
}

function isVoidish(type: Type): boolean {
  if (type.flags & (TypeFlags.Void | TypeFlags.Undefined | TypeFlags.Never)) return true;
  return type.isUnionType() && type.getTypes().every(isVoidish);
}

class Generator {
  private readonly signatures = new Map<number, readonly Signature[]>();
  private readonly properties = new Map<number, readonly Symbol[]>();
  private readonly checker: Checker;
  private readonly project: Project;
  private readonly anchor: Node;

  constructor(checker: Checker, project: Project, anchor: Node) {
    this.checker = checker;
    this.project = project;
    this.anchor = anchor;
  }

  generateRoot(type: Type): Map<string, string> {
    const files = new Map<string, string>();
    const surfaceImports: string[] = [];
    const surfaceFields: string[] = [];
    for (const prop of this.propsOf(type)) {
      const name = prop.name;
      console.log(`[browser-mock] ${name}`);
      const propType = this.concrete(this.propertyType(prop));
      if (this.callSignatures(propType).length === 0 && !this.isDataObject(propType)) {
        surfaceFields.push(
          ...this.place(ident(name), this.emitValue(propType, name, name, 0, []), 2),
        );
        continue;
      }
      if (this.callSignatures(propType).length > 0) {
        const fn = exportName(name);
        this.writeCreator(
          files,
          fn,
          `Window['electron'][${JSON.stringify(name)}]`,
          this.emitValue(propType, name, name, 0, []),
          false,
        );
        surfaceImports.push(`import { ${fn} } from './${fn}';`);
        surfaceFields.push(`    ${ident(name)}: ${fn}(runtime),`);
        continue;
      }
      const chunks = this.objectChunks(propType, name);
      const partNames = chunks.map((chunk, index) => {
        const fn = chunks.length === 1 ? exportName(name) : `${exportName(name)}Part${index}`;
        const returnType =
          chunks.length === 1
            ? `Window['electron'][${JSON.stringify(name)}]`
            : `Pick<Window['electron'][${JSON.stringify(name)}], ${chunk.name}>`;
        this.writeCreator(files, fn, returnType, ['{', ...this.indent(chunk.lines, 1), '}'], true);
        return fn;
      });
      for (const fn of partNames) surfaceImports.push(`import { ${fn} } from './${fn}';`);
      surfaceFields.push(
        partNames.length === 1
          ? `    ${ident(name)}: ${partNames[0]}(runtime),`
          : `    ${ident(name)}: { ${partNames.map(fn => `...${fn}(runtime)`).join(', ')} },`,
      );
    }
    const surface = `${HEADER}import type { BrowserMockRuntime } from '../runtime';\n${surfaceImports.join('\n')}\n\nexport function createGeneratedSurface(runtime: BrowserMockRuntime): Window['electron'] {\n  return {\n${surfaceFields.join('\n')}\n  };\n}\n`;
    files.set('surface.ts', surface);
    return files;
  }

  private writeCreator(
    files: Map<string, string>,
    fn: string,
    returnType: string,
    valueLines: string[],
    objectValue: boolean,
  ): void {
    const body = this.indent(
      valueLines.length === 1 && !objectValue
        ? [`return ${valueLines[0]};`]
        : ['return (', ...this.indent(valueLines, 1), ');'],
      1,
    );
    const param = body.some(line => line.includes('runtime.')) ? 'runtime' : '_runtime';
    files.set(
      `${fn}.ts`,
      `${HEADER}import type { BrowserMockRuntime } from '../runtime';\n\nexport function ${fn}(${param}: BrowserMockRuntime): ${returnType} {\n${body.join('\n')}\n}\n`,
    );
  }

  private objectChunks(type: Type, pathKey: string): PropChunk[] {
    const fields = this.objectFields(type, pathKey, 0, []);
    const chunks: PropChunk[] = [];
    let lines: string[] = [];
    let names: string[] = [];
    const flush = () => {
      if (lines.length === 0) return;
      chunks.push({ name: names.map(item => JSON.stringify(item)).join(' | '), lines });
      lines = [];
      names = [];
    };
    for (const field of fields) {
      if (lines.length > 0 && lines.length + field.lines.length > MAX_LINES) flush();
      names.push(field.name);
      lines.push(...field.lines);
    }
    flush();
    return chunks.length > 0 ? chunks : [{ name: 'never', lines: [] }];
  }

  private objectFields(
    type: Type,
    pathKey: string,
    depth: number,
    stack: number[],
  ): Array<{ name: string; lines: string[] }> {
    const hasSuccess =
      this.checker.getPropertyOfType(type, 'success') !== undefined ||
      this.checker.getPropertyOfType(type, 'ok') !== undefined;
    const fields: Array<{ name: string; lines: string[] }> = [];
    for (const prop of this.propsOf(type)) {
      const name = prop.name;
      const optional = (prop.flags & SymbolFlags.Optional) !== 0;
      const propType = this.concrete(this.propertyType(prop));
      if (optional && !this.includeOptional(name, propType, hasSuccess)) continue;
      const lines = this.emitValue(propType, name, `${pathKey}.${name}`, depth + 1, stack);
      fields.push({ name, lines: this.place(ident(name), lines, 0) });
    }
    return fields;
  }

  private includeOptional(name: string, type: Type, hasSuccess: boolean): boolean {
    if (TRUE_NAMES.has(name) || name === 'cancelled' || name === 'canceled') return true;
    if (this.arrayElement(type)) return true;
    if (!this.isDataObject(type)) return false;
    return hasSuccess || OPTIONAL_OBJECTS.has(name);
  }

  private emitValue(
    type: Type,
    name: string,
    pathKey: string,
    depth: number,
    stack: number[],
  ): string[] {
    if (depth > MAX_DEPTH) {
      throw new Error(`Depth limit at ${pathKey}: ${this.checker.typeToString(type)}`);
    }
    if (stack.includes(type.id)) {
      throw new Error(`Type cycle at ${pathKey}: ${this.checker.typeToString(type)}`);
    }
    if (type.isErrorType()) {
      console.warn(
        `[browser-mock] unresolved type at ${pathKey}: ${this.checker.typeToString(type)}`,
      );
      return ['null'];
    }
    const stripped = this.concrete(type);
    if (stripped.id !== type.id) return this.emitValue(stripped, name, pathKey, depth, stack);
    if (type.isUnionType()) return this.emitUnion(type, name, pathKey, depth, stack);
    if (type.isIntersectionType()) {
      const apparent = this.checker.getApparentType(type);
      if (apparent && apparent.id !== type.id)
        return this.emitValue(apparent, name, pathKey, depth, stack);
    }
    if (type.isTypeParameter()) {
      const constraint =
        this.checker.getConstraintOfTypeParameter(type) ??
        this.checker.getBaseConstraintOfType(type);
      if (constraint && constraint.id !== type.id)
        return this.emitValue(constraint, name, pathKey, depth, stack);
      return ['null'];
    }
    if (
      type.flags &
      (TypeFlags.IndexedAccess |
        TypeFlags.Conditional |
        TypeFlags.Substitution |
        TypeFlags.StringMapping)
    ) {
      const apparent = this.checker.getApparentType(type);
      if (apparent && apparent.id !== type.id)
        return this.emitValue(apparent, name, pathKey, depth, stack);
      if (type.flags & TypeFlags.StringMapping) return ["''"];
    }
    if (
      type.flags &
      (TypeFlags.Any | TypeFlags.Unknown | TypeFlags.Never | TypeFlags.Void | TypeFlags.Undefined)
    ) {
      return ['null'];
    }
    if (type.flags & TypeFlags.Null) return ['null'];
    if (type.isBooleanLiteralType()) return [type.value ? 'true' : 'false'];
    if (type.flags & TypeFlags.Boolean || type.flags & TypeFlags.BooleanLiteral) {
      return [TRUE_NAMES.has(name) ? 'true' : 'false'];
    }
    if (type.isStringLiteralType()) return [JSON.stringify(type.value)];
    if (type.flags & TypeFlags.EnumLiteral) {
      const value = this.literalValue(type);
      if (typeof value === 'string') return [JSON.stringify(value)];
      if (typeof value === 'number') return [String(value)];
    }
    if (type.isNumberLiteralType()) return [String(type.value)];
    if (type.isBigIntLiteralType()) return [`${type.value}n`];
    if (type.flags & TypeFlags.String) return [JSON.stringify(STRING_BY_NAME[name] ?? '')];
    if (type.isTemplateLiteralType()) return [JSON.stringify(this.templateSample(type))];
    if (type.flags & TypeFlags.Number) return [this.numberSample(name)];
    if (type.flags & TypeFlags.BigInt) return ['0n'];
    if (type.flags & TypeFlags.ESSymbol) return ['null'];
    if (this.callSignatures(type).length > 0) return this.emitFunction(type, pathKey);
    if (this.checker.isTupleType(type)) return this.emitTuple(type, name, pathKey, depth, stack);
    if (this.arrayElement(type)) return ['[]'];
    const promised = this.promiseInner(type);
    if (promised) {
      const inner = this.emitValue(promised, name, pathKey, depth + 1, stack);
      if (inner.length === 1) return [`Promise.resolve(${inner[0]})`];
      return ['Promise.resolve(', ...this.indent(inner, 1), ')'];
    }
    if (this.isDataObject(type) || type.flags & TypeFlags.NonPrimitive) {
      const fields = this.objectFields(type, pathKey, depth, [...stack, type.id]);
      if (fields.length === 0) return ['{}'];
      return ['{', ...fields.flatMap(field => this.indent(field.lines, 1)), '}'];
    }
    if (type.flags & TypeFlags.Enum) {
      const member = type.getSymbol()?.getExports().values().next().value;
      if (member) return this.emitValue(this.propertyType(member), name, pathKey, depth + 1, stack);
    }
    throw new Error(
      `Unsupported type at ${pathKey}: ${this.checker.typeToString(type)} flags=${type.flags}`,
    );
  }

  private emitUnion(
    type: Type,
    name: string,
    pathKey: string,
    depth: number,
    stack: number[],
  ): string[] {
    const parts = (type.isUnionType() ? type.getTypes() : []).filter(
      part => !(part.flags & (TypeFlags.Null | TypeFlags.Undefined | TypeFlags.Void)),
    );
    if (parts.length === 0) return ['null'];
    if (parts.every(part => part.isBooleanLiteralType())) {
      if (TRUE_NAMES.has(name)) return ['true'];
      return ['false'];
    }
    if (
      parts.every(
        part =>
          part.isStringLiteralType() ||
          part.flags & TypeFlags.EnumLiteral ||
          part.isNumberLiteralType(),
      ) &&
      parts.every(
        part =>
          part.isStringLiteralType() ||
          (part.flags & TypeFlags.EnumLiteral && typeof this.literalValue(part) === 'string'),
      )
    ) {
      const values = parts.map(part =>
        part.isStringLiteralType() ? part.value : String(this.literalValue(part) ?? ''),
      );
      const pick = PREFERRED_LITERALS.find(item => values.includes(item)) ?? values[0] ?? '';
      return [JSON.stringify(pick)];
    }
    const ranked = [...parts].sort((left, right) => this.unionScore(right) - this.unionScore(left));
    const chosen = ranked[0];
    if (!chosen) return ['null'];
    return this.emitValue(chosen, name, pathKey, depth, stack);
  }

  private unionScore(type: Type): number {
    if (
      this.boolProp(type, 'success') ||
      this.boolProp(type, 'ok') ||
      this.boolProp(type, 'loggedIn')
    )
      return 100;
    if (this.isDataObject(type)) return 50;
    if (type.flags & TypeFlags.String) return 20;
    if (type.flags & (TypeFlags.Number | TypeFlags.Boolean)) return 10;
    return 0;
  }

  private boolProp(type: Type, name: string): boolean {
    const prop = this.checker.getPropertyOfType(type, name);
    if (!prop) return false;
    const propType = this.propertyType(prop);
    return propType.isBooleanLiteralType() && propType.value === true;
  }

  private emitTuple(
    type: Type,
    name: string,
    pathKey: string,
    depth: number,
    stack: number[],
  ): string[] {
    if (!type.isTypeReference()) return ['[]'];
    const args = this.checker.getTypeArguments(type);
    if (args.length === 0) return ['[]'];
    const parts = args.map((part, index) =>
      this.emitValue(part, `${name}${index}`, `${pathKey}[${index}]`, depth + 1, stack),
    );
    if (parts.every(part => part.length === 1))
      return [`[${parts.map(part => part[0]).join(', ')}]`];
    return ['[', ...parts.flatMap(part => this.indent(part, 1)), ']'];
  }

  private emitFunction(type: Type, pathKey: string): string[] {
    const signature = this.callSignatures(type)[0];
    if (!signature) return ['() => undefined'];
    const params = signature.getParameters().filter(param => param.name !== 'this');
    const names = params.map((_, index) => `_p${index}`);
    const callbackIndex = this.callbackIndex(signature, params);
    const returned = this.checker.getReturnTypeOfSignature(signature) ?? this.checker.getVoidType();
    const unsubscribe = this.callSignatures(returned);
    const unsubscribeReturn = unsubscribe[0]
      ? (this.checker.getReturnTypeOfSignature(unsubscribe[0]) ?? this.checker.getVoidType())
      : undefined;
    if (
      callbackIndex >= 0 &&
      unsubscribe.length === 1 &&
      unsubscribeReturn &&
      isVoidish(unsubscribeReturn)
    ) {
      const unused = names.filter((_, index) => index !== callbackIndex);
      return [
        `(${names.join(', ')}) => {`,
        ...unused.map(param => `  void ${param};`),
        `  return runtime.subscribe(${JSON.stringify(pathKey)}, ${names[callbackIndex]});`,
        '}',
      ];
    }
    const promised = this.promiseInner(returned);
    const asyncFn = promised !== undefined;
    const valueType = promised ?? returned;
    const voids = names.map(param => `  void ${param};`);
    if (isVoidish(valueType)) {
      return [
        `${asyncFn ? 'async ' : ''}(${names.join(', ')}) => {`,
        ...voids,
        `  runtime.warnOnce(${JSON.stringify(pathKey)});`,
        '}',
      ];
    }
    const value = this.emitValue(valueType, pathKey.split('.').at(-1) ?? pathKey, pathKey, 0, []);
    const returnedLines =
      value.length === 1
        ? [`  return ${value[0]};`]
        : ['  return (', ...value.map(line => `    ${line}`), '  );'];
    return [
      `${asyncFn ? 'async ' : ''}(${names.join(', ')}) => {`,
      ...voids,
      `  runtime.warnOnce(${JSON.stringify(pathKey)});`,
      ...returnedLines,
      '}',
    ];
  }

  private callbackIndex(signature: Signature, params: readonly Symbol[]): number {
    const returned = this.checker.getReturnTypeOfSignature(signature);
    if (!returned) return -1;
    const calls = this.callSignatures(returned);
    const callReturn = calls[0] ? this.checker.getReturnTypeOfSignature(calls[0]) : undefined;
    if (calls.length !== 1 || !callReturn || !isVoidish(callReturn)) return -1;
    return params.findIndex(param => this.callSignatures(this.propertyType(param)).length > 0);
  }

  private concrete(type: Type): Type {
    const nonNull = this.checker.getNonNullableType(type);
    return nonNull ?? type;
  }

  private templateSample(type: Type): string {
    if (!type.isTemplateLiteralType()) return 'preview';
    const texts = type.texts;
    const types = type.getTypes();
    let sample = '';
    for (let index = 0; index < types.length; index += 1) {
      sample += texts[index] ?? '';
      const part = types[index];
      if (!part) continue;
      if (part.flags & TypeFlags.Number || part.isNumberLiteralType()) sample += '0';
      else if (part.isStringLiteralType()) sample += part.value;
      else sample += 'preview';
    }
    sample += texts[texts.length - 1] ?? '';
    return sample;
  }

  private numberSample(name: string): string {
    if (/At$|timestamp|time/i.test(name)) return String(Date.UTC(2026, 9, 16));
    if (name === 'status') return '200';
    return '0';
  }

  private isDataObject(type: Type): boolean {
    if (this.callSignatures(type).length > 0) return false;
    if (this.arrayElement(type) || this.checker.isTupleType(type) || this.promiseInner(type))
      return false;
    if (type.isObjectType() || type.isIntersectionType() || type.flags & TypeFlags.NonPrimitive)
      return true;
    if (type.flags & TypeFlags.Object) return true;
    return (type.objectFlags & ObjectFlags.Reference) !== 0;
  }

  private arrayElement(type: Type): Type | undefined {
    const name = type.getSymbol()?.name ?? type.getAliasSymbol()?.name;
    if (name !== 'Array' && name !== 'ReadonlyArray' && !this.checker.isArrayType(type))
      return undefined;
    if (!type.isTypeReference()) return undefined;
    return this.checker.getTypeArguments(type)[0];
  }

  private promiseInner(type: Type): Type | undefined {
    const name = type.getSymbol()?.name ?? type.getAliasSymbol()?.name;
    if (name !== 'Promise' || !type.isTypeReference()) return undefined;
    return this.checker.getTypeArguments(type)[0];
  }

  private callSignatures(type: Type): readonly Signature[] {
    const cached = this.signatures.get(type.id);
    if (cached) return cached;
    const found = this.checker.getSignaturesOfType(type, SignatureKind.Call);
    this.signatures.set(type.id, found);
    return found;
  }

  private propsOf(type: Type): readonly Symbol[] {
    const cached = this.properties.get(type.id);
    if (cached) return cached;
    const found = this.checker.getPropertiesOfType(type).filter(prop => {
      return prop.name !== 'prototype' && !prop.name.startsWith('__');
    });
    this.properties.set(type.id, found);
    return found;
  }

  private propertyType(prop: Symbol): Type {
    const handle = prop.valueDeclaration ?? prop.declarations[0];
    const node = handle?.resolve(this.project) ?? this.anchor;
    return this.checker.getTypeOfSymbolAtLocation(prop, node);
  }

  private literalValue(type: Type): string | number | boolean | bigint | undefined {
    if (!('value' in type)) return undefined;
    const value = type.value;
    if (
      typeof value === 'string' ||
      typeof value === 'number' ||
      typeof value === 'boolean' ||
      typeof value === 'bigint'
    ) {
      return value;
    }
    return undefined;
  }

  private place(key: string, valueLines: string[], indent: number): string[] {
    const pad = '  '.repeat(indent);
    if (valueLines.length === 1) return [`${pad}${key}: ${valueLines[0]},`];
    const lines = [`${pad}${key}: ${valueLines[0]}`];
    for (let index = 1; index < valueLines.length; index += 1) {
      const last = index === valueLines.length - 1;
      lines.push(`${pad}${valueLines[index]}${last ? ',' : ''}`);
    }
    return lines;
  }

  private indent(lines: string[], level: number): string[] {
    const pad = '  '.repeat(level);
    return lines.map(line => (line.length > 0 ? `${pad}${line}` : line));
  }
}

function writeFiles(dir: string, files: Map<string, string>): void {
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
  for (const [name, contents] of files) fs.writeFileSync(path.join(dir, name), contents);
}

function formatDir(dir: string): void {
  const bin = path.join(ROOT, 'node_modules/.bin/oxfmt');
  const result = spawnSync(bin, [dir], { cwd: ROOT, stdio: 'inherit' });
  if (result.status !== 0) throw new Error('oxfmt failed');
}

function diffDirs(left: string, right: string): string[] {
  const names = new Set([...fs.readdirSync(left), ...fs.readdirSync(right)]);
  const changes: string[] = [];
  for (const name of names) {
    const a = path.join(left, name);
    const b = path.join(right, name);
    const aText = fs.existsSync(a) ? fs.readFileSync(a, 'utf8') : '';
    const bText = fs.existsSync(b) ? fs.readFileSync(b, 'utf8') : '';
    if (aText !== bText) changes.push(name);
  }
  return changes;
}

function main(): void {
  const check = process.argv.includes('--check');
  const api = new API();
  try {
    const snapshot = api.updateSnapshot({ openProject: path.join(ROOT, 'tsconfig.json') });
    const project = snapshot.getProjects()[0];
    if (!project) throw new Error('tsconfig.json did not produce a project');
    const source = project.program.getSourceFile(
      path.join(ROOT, 'src/renderer/types/electron.d.ts'),
    );
    if (!source) throw new Error('electron.d.ts was not part of the program');
    let iface: Node | undefined;
    const visit = (node: Node): void => {
      if (iface) return;
      if (isInterfaceDeclaration(node) && node.name.text === 'IElectronAPI') {
        iface = node;
        return;
      }
      node.forEachChild(visit);
    };
    visit(source);
    if (!iface || !isInterfaceDeclaration(iface)) throw new Error('IElectronAPI was not found');
    const symbol = project.checker.getSymbolAtLocation(iface.name);
    if (!symbol) throw new Error('IElectronAPI has no symbol');
    const generator = new Generator(project.checker, project, iface);
    const files = generator.generateRoot(project.checker.getDeclaredTypeOfSymbol(symbol));
    const destination = check ? fs.mkdtempSync(path.join(os.tmpdir(), 'browser-mock-')) : OUT_DIR;
    writeFiles(destination, files);
    formatDir(destination);
    if (!check) {
      console.log(`[browser-mock] wrote ${files.size} files to ${path.relative(ROOT, OUT_DIR)}`);
      return;
    }
    const changes = diffDirs(OUT_DIR, destination);
    if (changes.length > 0) {
      console.error(`[browser-mock] generated surface is stale: ${changes.join(', ')}`);
      console.error('Run bun run web:preview:codegen and commit the result.');
      process.exit(1);
    }
    console.log('[browser-mock] generated surface is up to date');
  } finally {
    api.close();
  }
}

main();
